#include <iostream>
#include <unordered_map>
#include <utility>

using namespace std;

unordered_map<int, long long> dp1;
unordered_map<pair<int, int>, long long, hash<pair<int, int>>> dp2;

struct pair_hash {
    size_t operator()(const pair<int, int>& p) const {
        size_t seed = 0;
        seed ^= hash<int>()(p.first) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
        seed ^= hash<int>()(p.second) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
        return seed;
    }
};

long long compute_tree_counts(int n) {
    if (n < 0) {
        return 0;
    }
    if (n < 2) {
        return 1;
    }
    if (dp1.find(n) == dp1.end()) {
        long long total = 0;
        for (int i = 0; i < n; ++i) {
            total += compute_tree_counts(i) * compute_tree_counts(n - 1 - i);
        }
        dp1[n] = total;
    }
    return dp1[n];
}

long long compute_subtree_counts(int n, int h) {
    if (n < 0 || h <= 0 || n >= (1 << (h - 1))) {
        return 0;
    }
    if (n < 2) {
        return 1;
    }
    if (n < h) {
        return compute_tree_counts(n);
    }
    pair<int, int> key = make_pair(n, h);
    if (dp2.find(key) == dp2.end()) {
        long long total = 0;
        for (int i = 0; i < n; ++i) {
            total += compute_subtree_counts(i, h - 1) * compute_subtree_counts(n - 1 - i, h - 1);
        }
        dp2[key] = total;
    }
    return dp2[key];
}

int main() {
    int A, B;
    cin >> A >> B;
    cout << compute_tree_counts(A) - compute_subtree_counts(A, B) << endl;
    return 0;
}

